(2535146, 349960, 46314, '<td valign="top">Could have been cropped a little tighter on the left to get rid of that distracting light spill...</td>', 'Could have been cropped a little tighter on the left to get rid of that distracting light spill...', '2006-06-21 05:20:06.000000', NULL, 1),
(2535154, 349007, 60036, '<td valign="top">Spyrogyra sparklet, great patterns</td>', 'Spyrogyra sparklet, great patterns', '2006-06-21 05:30:53.000000', NULL, 1),
(2535160, 349759, 26679, '<td valign="top">Ah Honk Kong, it''s a great light show.<br/>I love how you captred the building. The one thing that is missing for me is some definition or colour in the sky. Ideally taking this shot a little earlier will give that.<br/>However I love this scene and spend a numbers of hous earlier in the year takingvery similar shots</td>', 'Ah Honk Kong, it''s a great light show.I love how you captred the building. The one thing that is missing for me is some definition or colour in the sky. Ideally taking this shot a little earlier will give that.However I love this scene and spend a numbers of hous earlier in the year takingvery similar shots', '2006-06-21 05:34:43.000000', NULL, 1),
(2535164, 350294, 60036, '<td valign="top">Works well</td>', 'Works well', '2006-06-21 05:38:08.000000', NULL, 1),
(2535175, 348765, 54778, '<td valign="top">Hmm.. How in the world did you get the light to work so well for you. The starry affect is lovely</td>', 'Hmm.. How in the world did you get the light to work so well for you. The starry affect is lovely', '2006-06-21 05:49:19.000000', NULL, 1),
(2535177, 351030, 45360, '<td valign="top">Love the title  :)</td>', 'Love the title  :)', '2006-06-21 05:50:27.000000', NULL, 1),
(2535189, 348911, 46314, '<td valign="top">Great song. Nice photo too..</td>', 'Great song. Nice photo too..', '2006-06-21 06:01:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2535202, 349441, 46314, '<td valign="top">Very funny.</td>', 'Very funny.', '2006-06-21 06:12:49.000000', NULL, 1),
(2535207, 348351, 50104, '<td valign="top">Not a bad image, but there just doesn''t seem to be a whole lot of point to this being 30sec or more. It just looks like daylight.</td>', 'Not a bad image, but there just doesn''t seem to be a whole lot of point to this being 30sec or more. It just looks like daylight.', '2006-06-21 06:16:29.000000', NULL, 1),
(2535213, 349901, 46314, '<td valign="top">Awesome shot. Love the "blurred walls of hyperspace" effect... And the exposure is perfect.</td>', 'Awesome shot. Love the "blurred walls of hyperspace" effect... And the exposure is perfect.', '2006-06-21 06:18:33.000000', NULL, 1),
(2535216, 350023, 21255, '<td valign="top">this is awesome! good luck</td>', 'this is awesome! good luck', '2006-06-21 06:18:50.000000', NULL, 1),
(2535241, 348911, 50104, '<td valign="top">Awesome! 10</td>', 'Awesome! 10', '2006-06-21 06:28:25.000000', NULL, 1),
(2535251, 349441, 54778, '<td valign="top">aww</td>', 'aww', '2006-06-21 06:32:44.000000', NULL, 1),
(2535257, 350629, 60803, '<td valign="top">Framing is a bit too bright &amp; distracting unfortunately.</td>', 'Framing is a bit too bright & distracting unfortunately.', '2006-06-21 06:38:00.000000', NULL, 1),
(2535259, 349098, 60803, '<td valign="top">Very clever idea, it might have looked better if you''d popped a flash a few times to give some ghosted fingers.</td>', 'Very clever idea, it might have looked better if you''d popped a flash a few times to give some ghosted fingers.', '2006-06-21 06:39:10.000000', NULL, 1),
(2535266, 351046, 60803, '<td valign="top">Oversharpening has somewhat spoiled what would have been a nice image without it.</td>', 'Oversharpening has somewhat spoiled what would have been a nice image without it.', '2006-06-21 06:44:36.000000', NULL, 1),
(2535270, 349496, 56658, '<td valign="top">I like the idea but the background leaves much to be desired.</td>', 'I like the idea but the background leaves much to be desired.', '2006-06-21 06:52:53.000000', NULL, 1),
(2535279, 347987, 56658, '<td valign="top">great effect from the clouds, good job</td>', 'great effect from the clouds, good job', '2006-06-21 06:56:51.000000', NULL, 1),
(2535281, 349419, 60803, '<td valign="top">The colour doesn''t really evoke a sense of calm.</td>', 'The colour doesn''t really evoke a sense of calm.', '2006-06-21 06:59:19.000000', NULL, 1),
(2535282, 350930, 56658, '<td valign="top">nicely done I would have liked it more if the midle one could have been solid</td>', 'nicely done I would have liked it more if the midle one could have been solid', '2006-06-21 06:59:52.000000', NULL, 1),
(2535288, 348950, 60803, '<td valign="top">Very clever idea.</td>', 'Very clever idea.', '2006-06-21 07:06:43.000000', NULL, 1),
(2535309, 350549, 54778, '<td valign="top">Lovely shot, I would have prefered it if the crop was a bit tighter</td>', 'Lovely shot, I would have prefered it if the crop was a bit tighter', '2006-06-21 07:26:21.000000', NULL, 1),
(2535313, 349690, 50715, '<td valign="top">Good image. I like the opposing focal points of the fire in the bottom left versus the concentric circles drawing the eye to the upper right. Adding a little more (but not too much!) lighting of the grass etc. in the central band of the photo would have enhanced I think... with an exposure as long as yours, this would have been possible with a handheld light or even a controlled off-camera flash. But overall well conceived and executed.</td>', 'Good image. I like the opposing focal points of the fire in the bottom left versus the concentric circles drawing the eye to the upper right. Adding a little more (but not too much!) lighting of the grass etc. in the central band of the photo would have enhanced I think... with an exposure as long as yours, this would have been possible with a handheld light or even a controlled off-camera flash. But overall well conceived and executed.', '2006-06-21 07:37:56.000000', NULL, 1),
(2535328, 348792, 54778, '<td valign="top">A the light needs to be a tad up but other than that its fine</td>', 'A the light needs to be a tad up but other than that its fine', '2006-06-21 07:45:55.000000', NULL, 1),
(2535351, 349689, 51540, '<td valign="top">Nice exposure, but the composition leaves a little to be desired.</td>', 'Nice exposure, but the composition leaves a little to be desired.', '2006-06-21 08:01:24.000000', NULL, 1),
(2535354, 350196, 51540, '<td valign="top">The dock is wonderfully exposed, but the blown out steeple is rather distracting.  Possibly a diferent angle, or a lower crop?</td>', 'The dock is wonderfully exposed, but the blown out steeple is rather distracting.  Possibly a diferent angle, or a lower crop?', '2006-06-21 08:03:50.000000', NULL, 1),
(2535355, 350041, 51540, '<td valign="top">Great lines and colors!</td>', 'Great lines and colors!', '2006-06-21 08:04:15.000000', NULL, 1),
(2535356, 348598, 27482, '<td valign="top">I dunno, cropping this to a panorama doesn´t really seem to do this shot justice, it just simply lacks visual impact at this pixel size, I have a feeling this would look much better printed out in 60x30cm on somebodys wall but in this web resolution, the impact is lost...  Nice shot though, don´t get me wrong.</td>', 'I dunno, cropping this to a panorama doesn´t really seem to do this shot justice, it just simply lacks visual impact at this pixel size, I have a feeling this would look much better printed out in 60x30cm on somebodys wall but in this web resolution, the impact is lost...  Nice shot though, don´t get me wrong.', '2006-06-21 08:04:33.000000', NULL, 1),
(2535357, 347813, 27482, '<td valign="top">Sorry but this doesn´t do anything for me, just not interesting and aesthetically pleasing to me.  The reason for this comment is that I make a rule commenting on shots I vote low and I gave this a 3.  Like that you are experimenting though, keep that up.</td>', 'Sorry but this doesn´t do anything for me, just not interesting and aesthetically pleasing to me.  The reason for this comment is that I make a rule commenting on shots I vote low and I gave this a 3.  Like that you are experimenting though, keep that up.', '2006-06-21 08:05:47.000000', NULL, 1),
(2535358, 348603, 51540, '<td valign="top">lasers are great fun!</td>', 'lasers are great fun!', '2006-06-21 08:05:59.000000', NULL, 1),
(2535359, 348505, 51540, '<td valign="top">IR?  Nice</td>', 'IR?  Nice', '2006-06-21 08:06:18.000000', NULL, 1),
(2535360, 349930, 51540, '<td valign="top">Wonderful lines!</td>', 'Wonderful lines!', '2006-06-21 08:06:44.000000', NULL, 1),
(2535363, 349689, 27482, '<td valign="top">This is pretty cool, however, the bright stones at the bottom are a bit of an attention stealer, if this were an advanced editing challenge I would have darkened them to be in theme with the rocks in the backround but I still really like it as it is, don´t get me wrong.  7 from me.</td>', 'This is pretty cool, however, the bright stones at the bottom are a bit of an attention stealer, if this were an advanced editing challenge I would have darkened them to be in theme with the rocks in the backround but I still really like it as it is, don´t get me wrong.  7 from me.', '2006-06-21 08:08:58.000000', NULL, 1),
(2535364, 350891, 51540, '<td valign="top">Nice shot, overall I would want it a little darker, but it looks good</td>', 'Nice shot, overall I would want it a little darker, but it looks good', '2006-06-21 08:09:41.000000', NULL, 1),
(2535365, 349441, 30637, '<td valign="top">Made me smile!</td>', 'Made me smile!', '2006-06-21 08:10:52.000000', NULL, 1),
(2535368, 349007, 51540, '<td valign="top">A human spirograph?  How did you get the lines so consistent?</td>', 'A human spirograph?  How did you get the lines so consistent?', '2006-06-21 08:12:45.000000', NULL, 1),
(2535370, 350147, 51540, '<td valign="top">Cool idea!  If it could have been sharper (strap the tripod down tighter?) and maybe a little higher angle to get more lights throught the window it would be awesome!</td>', 'Cool idea!  If it could have been sharper (strap the tripod down tighter?) and maybe a little higher angle to get more lights throught the window it would be awesome!', '2006-06-21 08:16:20.000000', NULL, 1),
(2535372, 349007, 51900, '<td valign="top">howd u make it so perfect?</td>', 'howd u make it so perfect?', '2006-06-21 08:17:49.000000', NULL, 1),
(2535375, 351032, 51540, '<td valign="top">Nice shot!  I''d love to see this at 1/250 so I can see what this water looks like really.  It looks so serene here!</td>', 'Nice shot!  I''d love to see this at 1/250 so I can see what this water looks like really.  It looks so serene here!', '2006-06-21 08:18:36.000000', NULL, 1),
(2535378, 349901, 27482, '<td valign="top">Pretty cool shot!  The blown headlights are bothering me somewhat but not a whole lot, just would have looked better if you hadn´t left them on the whole time but turned them on just for the last second or two to keep them less exposed but other than that, this shot is ACE!  Not enough for a 10 from me though but close enough, got a 9 from me.</td>', 'Pretty cool shot!  The blown headlights are bothering me somewhat but not a whole lot, just would have looked better if you hadn´t left them on the whole time but turned them on just for the last second or two to keep them less exposed but other than that, this shot is ACE!  Not enough for a 10 from me though but close enough, got a 9 from me.', '2006-06-21 08:19:48.000000', NULL, 1),
(2535379, 348886, 51540, '<td valign="top">Cute, how many takes did this take?</td>', 'Cute, how many takes did this take?', '2006-06-21 08:20:55.000000', NULL, 1),
(2535383, 347944, 51540, '<td valign="top">Without the birdhouse, and an off-center crop maybe?</td>', 'Without the birdhouse, and an off-center crop maybe?', '2006-06-21 08:22:32.000000', NULL, 1),
(2535384, 349821, 51540, '<td valign="top">Ouch!, thats a bunch o'' dust-bunnies!</td>', 'Ouch!, thats a bunch o'' dust-bunnies!', '2006-06-21 08:24:20.000000', NULL, 1),
(2535387, 348409, 51540, '<td valign="top">Fun one!</td>', 'Fun one!', '2006-06-21 08:26:29.000000', NULL, 1),
(2535389, 350989, 51540, '<td valign="top">a little soft?</td>', 'a little soft?', '2006-06-21 08:27:18.000000', NULL, 1),
(2535390, 351032, 27482, '<td valign="top">Nice shot, taken at the exact right time of day, nice work.  7 from me.</td>', 'Nice shot, taken at the exact right time of day, nice work.  7 from me.', '2006-06-21 08:27:38.000000', NULL, 1),
(2535391, 349441, 51540, '<td valign="top">Ha ha, very cute!</td>', 'Ha ha, very cute!', '2006-06-21 08:28:03.000000', NULL, 1),
(2535400, 349978, 56167, '<td valign="top">to bright</td>', 'to bright', '2006-06-21 08:33:05.000000', NULL, 1),
(2535402, 348910, 51540, '<td valign="top">Nice capture of this all too common feeling! Fun one!</td>', 'Nice capture of this all too common feeling! Fun one!', '2006-06-21 08:34:34.000000', NULL, 1),
(2535412, 350982, 27482, '<td valign="top">Sorry, don´t want to offend you but I make a rule of leaving a comment when I leave really low scores and I gave this a 2.  The reason is that when I view this photo, I just see a blurry blob of nothing that makes sense to me, this is way too artsy and abstract for my taste and frankly I do not like it.  Thought you at least deserved an explanation why I voted like that.  If you like this, that´s all that matters though so don´t listen to me.</td>', 'Sorry, don´t want to offend you but I make a rule of leaving a comment when I leave really low scores and I gave this a 2.  The reason is that when I view this photo, I just see a blurry blob of nothing that makes sense to me, this is way too artsy and abstract for my taste and frankly I do not like it.  Thought you at least deserved an explanation why I voted like that.  If you like this, that´s all that matters though so don´t listen to me.', '2006-06-21 08:37:35.000000', NULL, 1),
(2535422, 350912, 56167, '<td valign="top">looks nice</td>', 'looks nice', '2006-06-21 08:40:54.000000', NULL, 1),
(2535426, 350693, 27482, '<td valign="top">Nice idea, I think I would have liked this better if the "soul" were more transparent but it works like it is.</td>', 'Nice idea, I think I would have liked this better if the "soul" were more transparent but it works like it is.', '2006-06-21 08:42:34.000000', NULL, 1),
(2535429, 349441, 27482, '<td valign="top">Can man?  :)  Nice idea and good job on the light painting but the lack of focus TOTALLY kills this image, sorry but I can´t bring myself to give more than a 3.</td>', 'Can man?  :)  Nice idea and good job on the light painting but the lack of focus TOTALLY kills this image, sorry but I can´t bring myself to give more than a 3.', '2006-06-21 08:43:20.000000', NULL, 1),
(2535437, 349961, 27482, '<td valign="top">Nice, but the composition isn´t working for me here, I would have liked this better if you had gotten even lower to the ground wich means getting more of a curve in the sidewalk and leaned the camera more up in the left corner, having the lightpost to the right side up in the right corner as the part that is to the right of that lightpost doesn´t really do anything for the image.  Am I making any sense?  Also taken this earlier in the night, getting a slightly blue hue to the sky would have improved this shot, the sky part is not as interesting as it could be.</td>', 'Nice, but the composition isn´t working for me here, I would have liked this better if you had gotten even lower to the ground wich means getting more of a curve in the sidewalk and leaned the camera more up in the left corner, having the lightpost to the right side up in the right corner as the part that is to the right of that lightpost doesn´t really do anything for the image.  Am I making any sense?  Also taken this earlier in the night, getting a slightly blue hue to the sky would have improved this shot, the sky part is not as interesting as it could be.', '2006-06-21 08:45:43.000000', NULL, 1),
(2535487, 349690, 27482, '<td valign="top">Pretty cool shot, I threw a 6 on it, needs a more interesting or spectacular foreground to win me over (remember, I live in the northern hemisphere and have seen TONS of similar shots) but nice work.</td>', 'Pretty cool shot, I threw a 6 on it, needs a more interesting or spectacular foreground to win me over (remember, I live in the northern hemisphere and have seen TONS of similar shots) but nice work.', '2006-06-21 09:07:40.000000', NULL, 1),
(2535492, 348661, 27482, '<td valign="top">I normally don´t comment on frames but this one bothers me a bit as it´s kind of an attention stealer from the phot, not going to let that affect my score though.  However, the photo itself could use some better clarity, focus, sharpness, whatever since it seems a bit "fuzzy" for my taste.</td>', 'I normally don´t comment on frames but this one bothers me a bit as it´s kind of an attention stealer from the phot, not going to let that affect my score though.  However, the photo itself could use some better clarity, focus, sharpness, whatever since it seems a bit "fuzzy" for my taste.', '2006-06-21 09:08:58.000000', NULL, 1),
(2535494, 349419, 27482, '<td valign="top">Nice shot, the flare around the sun that crosses over the horizon bothers me a bit though and I think I would have liked an "after the sun goes below the horizion" shot better, would have given you a chance of an even longer shutter, softer and brighter dark areas of the photo and given it more of an balance.  Still nice, don´t get me wrong so I gave it a 6.</td>', 'Nice shot, the flare around the sun that crosses over the horizon bothers me a bit though and I think I would have liked an "after the sun goes below the horizion" shot better, would have given you a chance of an even longer shutter, softer and brighter dark areas of the photo and given it more of an balance.  Still nice, don´t get me wrong so I gave it a 6.', '2006-06-21 09:11:04.000000', NULL, 1),
