(2538682, 350982, 55956, '<td valign="top">very good abstract.</td>', 'very good abstract.', '2006-06-21 22:21:40.000000', NULL, 1),
(2538687, 350224, 60735, '<td valign="top">too busy</td>', 'too busy', '2006-06-21 22:23:11.000000', NULL, 1),
(2538689, 349930, 60735, '<td valign="top">nice composition - good lines -</td>', 'nice composition - good lines -', '2006-06-21 22:24:02.000000', NULL, 1),
(2538693, 350187, 60735, '<td valign="top">great colors</td>', 'great colors', '2006-06-21 22:24:44.000000', NULL, 1),
(2538697, 349572, 60735, '<td valign="top">adding sepia made this photo - it could have been taken 50years ago. I like that there are no true modern day images</td>', 'adding sepia made this photo - it could have been taken 50years ago. I like that there are no true modern day images', '2006-06-21 22:25:41.000000', NULL, 1),
(2538705, 347944, 55956, '<td valign="top">The idea is for 10!</td>', 'The idea is for 10!', '2006-06-21 22:26:50.000000', NULL, 1),
(2538710, 350194, 60735, '<td valign="top">several entries were of the ticking clock - this one is too centered and maybe too large to have an impact</td>', 'several entries were of the ticking clock - this one is too centered and maybe too large to have an impact', '2006-06-21 22:27:31.000000', NULL, 1),
(2538712, 350988, 60735, '<td valign="top">not quickly enough - there is not enough motion</td>', 'not quickly enough - there is not enough motion', '2006-06-21 22:28:00.000000', NULL, 1),
(2538716, 349758, 60735, '<td valign="top">having the second hand would have helped.</td>', 'having the second hand would have helped.', '2006-06-21 22:28:58.000000', NULL, 1),
(2538723, 350991, 60735, '<td valign="top">it looks like a runway to an alien ship</td>', 'it looks like a runway to an alien ship', '2006-06-21 22:30:08.000000', NULL, 1),
(2538727, 348765, 60735, '<td valign="top">take the model out of the picture (or have him totally dark) would have made this shot much better.</td>', 'take the model out of the picture (or have him totally dark) would have made this shot much better.', '2006-06-21 22:31:03.000000', NULL, 1),
(2538732, 350843, 60735, '<td valign="top">complete beauty.</td>', 'complete beauty.', '2006-06-21 22:32:01.000000', NULL, 1),
(2538749, 350846, 60735, '<td valign="top">gorgeous</td>', 'gorgeous', '2006-06-21 22:37:25.000000', NULL, 1),
(2538755, 349732, 45586, '<td valign="top">Hehehehe this is great!</td>', 'Hehehehe this is great!', '2006-06-21 22:39:23.000000', NULL, 1),
(2538756, 349232, 45586, '<td valign="top">Great smooth silky waters!</td>', 'Great smooth silky waters!', '2006-06-21 22:39:47.000000', NULL, 1),
(2538757, 349801, 45586, '<td valign="top">Wow! Amazing shot!</td>', 'Wow! Amazing shot!', '2006-06-21 22:40:00.000000', NULL, 1),
(2538761, 350846, 45586, '<td valign="top">How you managed to get the sky red and maintain the green of the grass is beyond me. Good photo but I have my doubts about the editing.</td>', 'How you managed to get the sky red and maintain the green of the grass is beyond me. Good photo but I have my doubts about the editing.', '2006-06-21 22:43:01.000000', NULL, 1),
(2538767, 350044, 45586, '<td valign="top">Great colors. The post processing is really surreal. The grass is fuzzy but that''s what makes it surreal. One of my faves and into my faves.</td>', 'Great colors. The post processing is really surreal. The grass is fuzzy but that''s what makes it surreal. One of my faves and into my faves.', '2006-06-21 22:43:46.000000', NULL, 1),
(2538770, 349930, 45586, '<td valign="top">Great photo but too bad for the typo ;(</td>', 'Great photo but too bad for the typo ;(', '2006-06-21 22:44:55.000000', NULL, 1),
(2538772, 349441, 38706, '<td valign="top">LOL :-)  Great idea</td>', 'LOL :-)  Great idea', '2006-06-21 22:45:17.000000', NULL, 1),
(2538773, 349134, 45586, '<td valign="top">Gorgeous. The lights on lower right is distracting though.</td>', 'Gorgeous. The lights on lower right is distracting though.', '2006-06-21 22:45:31.000000', NULL, 1),
(2538808, 348412, 50715, '<td valign="top">Impressive image! I like the fact that you the flames go right to edge/corner of frames to reinforce the depth and feel of being "inside the box". If you wanted to, you could experiment with putting some sort of object at the end of the tunnel to add interest to the focal point.</td>', 'Impressive image! I like the fact that you the flames go right to edge/corner of frames to reinforce the depth and feel of being "inside the box". If you wanted to, you could experiment with putting some sort of object at the end of the tunnel to add interest to the focal point.', '2006-06-21 22:57:08.000000', NULL, 1),
(2538825, 350028, 50715, '<td valign="top">I quite like this, an interesting take on a portrait/self-portrait. I''ll be interested to see how you did it because it looked like it was manipulated. The red showing on the collar of the lower-left portrait is a little distracting. I''m in two minds about whether the large dark space in lower right is a little too large or not - but maybe that''s part of the image, staring into nothingness.</td>', 'I quite like this, an interesting take on a portrait/self-portrait. I''ll be interested to see how you did it because it looked like it was manipulated. The red showing on the collar of the lower-left portrait is a little distracting. I''m in two minds about whether the large dark space in lower right is a little too large or not - but maybe that''s part of the image, staring into nothingness.', '2006-06-21 23:02:59.000000', NULL, 1),
(2538830, 349098, 50715, '<td valign="top">Good image, and the monochrome works nicely for it.</td>', 'Good image, and the monochrome works nicely for it.', '2006-06-21 23:04:28.000000', NULL, 1),
(2538848, 348886, 50715, '<td valign="top">I like this image - the way the model is staring off into the middle distance suggests some sort of scary evil. The middle part has the most expressive face, it would be intreesting to see another version with a little more expression of fear, loathing or shock on the other two. Choice of simple white clothing helps to keep attention on the three faces, without hiding the fact that she is an attractive model.<br/></td>', 'I like this image - the way the model is staring off into the middle distance suggests some sort of scary evil. The middle part has the most expressive face, it would be intreesting to see another version with a little more expression of fear, loathing or shock on the other two. Choice of simple white clothing helps to keep attention on the three faces, without hiding the fact that she is an attractive model.', '2006-06-21 23:09:28.000000', NULL, 1),
(2538857, 348762, 50715, '<td valign="top">Interesting infra-red type feel. Good composition. Normally I like saturated colours but the purple is just a little too intense for me.</td>', 'Interesting infra-red type feel. Good composition. Normally I like saturated colours but the purple is just a little too intense for me.', '2006-06-21 23:11:25.000000', NULL, 1),
(2538866, 348934, 50715, '<td valign="top">Mmm, I know what you mean, having used ND8 in some of my outtakes and in waterfall shots at other times. I quite like the nice generally-even lighting on this (i.e. no particular "hot spots" of foliage with the rest being quite dark), well visualised and composed.</td>', 'Mmm, I know what you mean, having used ND8 in some of my outtakes and in waterfall shots at other times. I quite like the nice generally-even lighting on this (i.e. no particular "hot spots" of foliage with the rest being quite dark), well visualised and composed.', '2006-06-21 23:13:43.000000', NULL, 1),
(2538873, 350053, 50715, '<td valign="top">I like the placid feel of this scene (which it would have lacked if there was a lot of wind or boat traffic), but I''m having trouble deciding whether I like the colours or not - perhaps it has lost a bit too much blue?</td>', 'I like the placid feel of this scene (which it would have lacked if there was a lot of wind or boat traffic), but I''m having trouble deciding whether I like the colours or not - perhaps it has lost a bit too much blue?', '2006-06-21 23:15:53.000000', NULL, 1),
(2538888, 349758, 50715, '<td valign="top">Nice clean composition and sharpness, but this image doesn''t really "pop" for me. I wouldn''t hang it on my wall, but it might work as a stock image.</td>', 'Nice clean composition and sharpness, but this image doesn''t really "pop" for me. I wouldn''t hang it on my wall, but it might work as a stock image.', '2006-06-21 23:18:32.000000', NULL, 1),
(2538898, 350194, 50715, '<td valign="top">Interesting take on how to do a long exposure! I like what you''ve done in terms of composing and choosing how to expose, but the clock does look a bit of out focus which is distracting.</td>', 'Interesting take on how to do a long exposure! I like what you''ve done in terms of composing and choosing how to expose, but the clock does look a bit of out focus which is distracting.', '2006-06-21 23:20:13.000000', NULL, 1),
(2538903, 350999, 42100, '<td valign="top">Very artistic and awesome color tones.  Very nice!</td>', 'Very artistic and awesome color tones.  Very nice!', '2006-06-21 23:22:01.000000', NULL, 1),
(2538907, 348886, 42100, '<td valign="top">Creative and well executed.  Great job!</td>', 'Creative and well executed.  Great job!', '2006-06-21 23:22:36.000000', NULL, 1),
(2538911, 350416, 50715, '<td valign="top">Interesting abstract! I think it might work a bit better if the contrast between the bottom left and top right corners wasn''t quite so strong?</td>', 'Interesting abstract! I think it might work a bit better if the contrast between the bottom left and top right corners wasn''t quite so strong?', '2006-06-21 23:23:31.000000', NULL, 1),
(2538912, 349888, 42100, '<td valign="top">Very nice composition.  Lots of leading lines in this one when you look closely.  Great job!</td>', 'Very nice composition.  Lots of leading lines in this one when you look closely.  Great job!', '2006-06-21 23:23:37.000000', NULL, 1),
(2538914, 348881, 50715, '<td valign="top">I like your subject and framing, but the orange is a little to intense, and the green a little too muted, for my mind.</td>', 'I like your subject and framing, but the orange is a little to intense, and the green a little too muted, for my mind.', '2006-06-21 23:25:00.000000', NULL, 1),
(2538916, 349745, 18197, '<td valign="top">This is 250 x 166. Why so small? Next time please make it bigger (640 on longest side) so I can see the details.</td>', 'This is 250 x 166. Why so small? Next time please make it bigger (640 on longest side) so I can see the details.', '2006-06-21 23:25:20.000000', NULL, 1),
(2538920, 350187, 42100, '<td valign="top">Great photo, very well composed with great lighting.  Only the sensor dust keeps this from going straight to the top.  Very interesting design to that building.</td>', 'Great photo, very well composed with great lighting.  Only the sensor dust keeps this from going straight to the top.  Very interesting design to that building.', '2006-06-21 23:26:23.000000', NULL, 1),
(2538926, 350041, 50715, '<td valign="top">The composition looks good to me, and the central horizon works better here than it would in some other images, but I think it would be improved if the foreground was lit a little bit more strongly rather than being so dark and featureless - unless it is sufficiently messy that you were *trying* to keep it dark? In which case shooting from a different position may have been better.</td>', 'The composition looks good to me, and the central horizon works better here than it would in some other images, but I think it would be improved if the foreground was lit a little bit more strongly rather than being so dark and featureless - unless it is sufficiently messy that you were *trying* to keep it dark? In which case shooting from a different position may have been better.', '2006-06-21 23:27:17.000000', NULL, 1),
(2538927, 350626, 42100, '<td valign="top">Very nice compostion, the light streaks divide the photo nicely and create good balance.  Well done!</td>', 'Very nice compostion, the light streaks divide the photo nicely and create good balance.  Well done!', '2006-06-21 23:27:23.000000', NULL, 1),
(2538937, 350722, 50715, '<td valign="top">I like the simple composition, but the image doesn''t really do much for me, it''s a little too plain. The plants show a bit of motion blur but only enough to appear out of focus, rather than the result of long exposure.</td>', 'I like the simple composition, but the image doesn''t really do much for me, it''s a little too plain. The plants show a bit of motion blur but only enough to appear out of focus, rather than the result of long exposure.', '2006-06-21 23:29:33.000000', NULL, 1),
(2538950, 350053, 42100, '<td valign="top">Very nice lighting and exposure.  With those great vertical lines from the reflections some more space at the bottom to accenuate them could be nice.  But with a great photo like this I should just keep my opinions to myself!</td>', 'Very nice lighting and exposure.  With those great vertical lines from the reflections some more space at the bottom to accenuate them could be nice.  But with a great photo like this I should just keep my opinions to myself!', '2006-06-21 23:31:06.000000', NULL, 1),
(2538956, 348832, 42100, '<td valign="top">Great star trails over Half Dome.  Very well composed and a beautiful photo.</td>', 'Great star trails over Half Dome.  Very well composed and a beautiful photo.', '2006-06-21 23:32:05.000000', NULL, 1),
(2538962, 349399, 18197, '<td valign="top">There are those who would disagree ... but please level the horizon ... or else, make it so slanted I know it''s on purpose.</td>', 'There are those who would disagree ... but please level the horizon ... or else, make it so slanted I know it''s on purpose.', '2006-06-21 23:33:57.000000', NULL, 1),
(2538965, 350041, 42100, '<td valign="top">Stunning clarity and color.  Also a very composition that gives depth to this photo.  Nicely done!</td>', 'Stunning clarity and color.  Also a very composition that gives depth to this photo.  Nicely done!', '2006-06-21 23:34:08.000000', NULL, 1),
(2538973, 348792, 50715, '<td valign="top">Sometimes you can get very powerful colours in night shots - but this one looks quite plain and dull. It doesn''t quite have the richness that morning light can bring, and the rest of the scene is quite dull and difficult to differentiate - which I suspect you did deliberately to compensate for the fact that it''s messy? In your desire to capture the boat relic, I think you''ve had to compromise too much on other things, leaving the result a bit dull. Sorry.</td>', 'Sometimes you can get very powerful colours in night shots - but this one looks quite plain and dull. It doesn''t quite have the richness that morning light can bring, and the rest of the scene is quite dull and difficult to differentiate - which I suspect you did deliberately to compensate for the fact that it''s messy? In your desire to capture the boat relic, I think you''ve had to compromise too much on other things, leaving the result a bit dull. Sorry.', '2006-06-21 23:36:00.000000', NULL, 1),
(2538978, 350798, 18197, '<td valign="top">Way out of the DPC box. Congratulations on that. Points for creativity.</td>', 'Way out of the DPC box. Congratulations on that. Points for creativity.', '2006-06-21 23:36:34.000000', NULL, 1),
(2538986, 347987, 23953, '<td valign="top">One of the best in the challenge. I love the moving clouds, the CN tower is massive against the cityscape. Good Luck</td>', 'One of the best in the challenge. I love the moving clouds, the CN tower is massive against the cityscape. Good Luck', '2006-06-21 23:37:30.000000', NULL, 1),
(2539000, 349888, 23953, '<td valign="top">I really enjoy looking at this shot...you should put this on DCPrints.....probably get some takers. I like the perspective and how the cityline is in the background. My only little gripe is the blownout light in the center of the frame, a little hot. Good luck though, this is great</td>', 'I really enjoy looking at this shot...you should put this on DCPrints.....probably get some takers. I like the perspective and how the cityline is in the background. My only little gripe is the blownout light in the center of the frame, a little hot. Good luck though, this is great', '2006-06-21 23:39:38.000000', NULL, 1),
(2539012, 348791, 50715, '<td valign="top">Sorry, but this image doesn''t do anything for me at all, the subject isn''t of interest, the composition is ok but not great, and it looks like you''ve treated the 30 second aspect as a technical difficulty to work around with a steady tripod, rather than an opportunity to do something different to a short exposure.</td>', 'Sorry, but this image doesn''t do anything for me at all, the subject isn''t of interest, the composition is ok but not great, and it looks like you''ve treated the 30 second aspect as a technical difficulty to work around with a steady tripod, rather than an opportunity to do something different to a short exposure.', '2006-06-21 23:41:44.000000', NULL, 1),
(2539029, 348464, 50715, '<td valign="top">Sorry, this doesn''t do much for me. The highlights are too blown out with the shadows too dark, and there composition is pretty plan. Looks like a 30-second grab shot.</td>', 'Sorry, this doesn''t do much for me. The highlights are too blown out with the shadows too dark, and there composition is pretty plan. Looks like a 30-second grab shot.', '2006-06-21 23:44:57.000000', NULL, 1),
(2539046, 349519, 50715, '<td valign="top">I think you''ve gone too wide here, so there is more attention on the buildings (boat yards? at first I thought they were cars being stripped!) and less on the lightning, with the landscape becoming black and featureless. I''d suggest zooming in further, and allowing the landscape to be exposured a little more strongly to add some feature.</td>', 'I think you''ve gone too wide here, so there is more attention on the buildings (boat yards? at first I thought they were cars being stripped!) and less on the lightning, with the landscape becoming black and featureless. I''d suggest zooming in further, and allowing the landscape to be exposured a little more strongly to add some feature.', '2006-06-21 23:47:12.000000', NULL, 1),
(2539061, 351046, 50715, '<td valign="top">Interesting idea, but all the wiggly lines - particularly the ones in forefround on the car tire and door, but also the cumulative impact of all of them together - become way too distracting and ruin what could otherwise have been a pleasing image.</td>', 'Interesting idea, but all the wiggly lines - particularly the ones in forefround on the car tire and door, but also the cumulative impact of all of them together - become way too distracting and ruin what could otherwise have been a pleasing image.', '2006-06-21 23:49:08.000000', NULL, 1),
(2539076, 347813, 50715, '<td valign="top">The rest of the image is just too murky for me. It would be better if the background was really dark/black, or if it had a bit of colour in it - but as it is, it''s a dull featureless grey that looks very pixellated, and that''s distracting.</td>', 'The rest of the image is just too murky for me. It would be better if the background was really dark/black, or if it had a bit of colour in it - but as it is, it''s a dull featureless grey that looks very pixellated, and that''s distracting.', '2006-06-21 23:50:50.000000', NULL, 1),
(2539094, 349134, 50715, '<td valign="top">This feels overexposed to me - the bright lights at the bottom flaring too much, and the sky feels too bright-orange, a bit off-putting. It could be improved if you were able to find an angle that included the building (or most of it) but excluded the cranes.</td>', 'This feels overexposed to me - the bright lights at the bottom flaring too much, and the sky feels too bright-orange, a bit off-putting. It could be improved if you were able to find an angle that included the building (or most of it) but excluded the cranes.', '2006-06-21 23:52:33.000000', NULL, 1),
(2539110, 348548, 50715, '<td valign="top">This reeks a little too much of an advertising shot for my liking - nice if you like that sort of thing, but I don''t. The non-moving parts of the watch face aren''t quite as sharp as it should be either. As much as I like negative space, the big black expanse in the top right corner isn''t really adding anything to this image.<br/></td>', 'This reeks a little too much of an advertising shot for my liking - nice if you like that sort of thing, but I don''t. The non-moving parts of the watch face aren''t quite as sharp as it should be either. As much as I like negative space, the big black expanse in the top right corner isn''t really adding anything to this image.', '2006-06-21 23:54:59.000000', NULL, 1),
(2539123, 350843, 42100, '<td valign="top">Nicely done.  Very brightly lit but lots of great detail with all the stars.  Good composition also.</td>', 'Nicely done.  Very brightly lit but lots of great detail with all the stars.  Good composition also.', '2006-06-21 23:56:52.000000', NULL, 1),
(2539127, 349753, 50715, '<td valign="top">Composition/framing is ok, but the bridge seems a bit hazy - could be motion blur I guess. Overall it''s a bit dark, I think I''d like this more if the sky was a bit lighter - dark/midnight blue rather than grey/black?</td>', 'Composition/framing is ok, but the bridge seems a bit hazy - could be motion blur I guess. Overall it''s a bit dark, I think I''d like this more if the sky was a bit lighter - dark/midnight blue rather than grey/black?', '2006-06-21 23:56:59.000000', NULL, 1),
(2539144, 348910, 54022, '<td valign="top">Amazingly still for 30 seconds....</td>', 'Amazingly still for 30 seconds....', '2006-06-21 23:59:00.000000', NULL, 1),
(2539161, 349947, 54022, '<td valign="top">Has a surrealistic appeal</td>', 'Has a surrealistic appeal', '2006-06-22 00:01:35.000000', NULL, 1),
(2539207, 348832, 54022, '<td valign="top">if the sky were a little darker, the effect wud have been stunning. Still looks great though.</td>', 'if the sky were a little darker, the effect wud have been stunning. Still looks great though.', '2006-06-22 00:08:36.000000', NULL, 1),
(2539217, 349758, 42826, '<td valign="top">what a lovely clock...love the golds in it!  the image is so soft....</td>', 'what a lovely clock...love the golds in it!  the image is so soft....', '2006-06-22 00:10:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2539243, 349745, 54022, '<td valign="top">Too small an image to be appreciated. A bigger photo wud have helped.</td>', 'Too small an image to be appreciated. A bigger photo wud have helped.', '2006-06-22 00:13:07.000000', NULL, 1),
(2539252, 350511, 54022, '<td valign="top">Timeless. As always...nice shot.</td>', 'Timeless. As always...nice shot.', '2006-06-22 00:14:04.000000', NULL, 1),
(2539268, 348409, 54022, '<td valign="top">technically sound...idea is real nice.</td>', 'technically sound...idea is real nice.', '2006-06-22 00:17:00.000000', NULL, 1),
(2539305, 349084, 59534, '<td valign="top">It could use better balance.  The lower portion is well-executed.</td>', 'It could use better balance.  The lower portion is well-executed.', '2006-06-22 00:29:50.000000', NULL, 1),
(2539325, 349399, 59534, '<td valign="top">Love the color, composition, and depth of field. Well done.</td>', 'Love the color, composition, and depth of field. Well done.', '2006-06-22 00:35:12.000000', NULL, 1),
(2539338, 350606, 59534, '<td valign="top">I wish the flag were in a different position. I do like the colors.</td>', 'I wish the flag were in a different position. I do like the colors.', '2006-06-22 00:39:02.000000', NULL, 1),
(2539347, 349978, 59534, '<td valign="top">Not your typical city-scape</td>', 'Not your typical city-scape', '2006-06-22 00:40:41.000000', NULL, 1),
(2539352, 349947, 59534, '<td valign="top">I like the colors and the composition.</td>', 'I like the colors and the composition.', '2006-06-22 00:41:53.000000', NULL, 1),
(2539354, 349690, 59534, '<td valign="top">Dizzying ...</td>', 'Dizzying ...', '2006-06-22 00:42:18.000000', NULL, 1),
(2539358, 350510, 59534, '<td valign="top">Slick</td>', 'Slick', '2006-06-22 00:42:39.000000', NULL, 1),
(2539364, 350175, 58785, '<td valign="top">Very cool... What''s that, computer screen? :P</td>', 'Very cool... What''s that, computer screen? :P', '2006-06-22 00:43:41.000000', NULL, 1),
(2539369, 348911, 58785, '<td valign="top">Nice. I love the colors... Very nice job...</td>', 'Nice. I love the colors... Very nice job...', '2006-06-22 00:44:07.000000', NULL, 1),
(2539371, 349875, 58785, '<td valign="top">Very cool... Excellent shot and colors are nice too :)</td>', 'Very cool... Excellent shot and colors are nice too :)', '2006-06-22 00:44:34.000000', NULL, 1),
(2539373, 349441, 58785, '<td valign="top">Now that''s funny... and a little fuzzy :P but still... funny :)</td>', 'Now that''s funny... and a little fuzzy :P but still... funny :)', '2006-06-22 00:44:58.000000', NULL, 1),
(2539376, 351032, 58785, '<td valign="top">Nice light work :D cool ;)</td>', 'Nice light work :D cool ;)', '2006-06-22 00:45:19.000000', NULL, 1),
(2539380, 349961, 58785, '<td valign="top">Cool fisheye 30 second shot :D</td>', 'Cool fisheye 30 second shot :D', '2006-06-22 00:45:39.000000', NULL, 1),
(2539385, 349300, 59534, '<td valign="top">Nice, but the foreground is distracting.</td>', 'Nice, but the foreground is distracting.', '2006-06-22 00:46:21.000000', NULL, 1),
(2539386, 349938, 58785, '<td valign="top">WHOA... Zeus at work :) Very cool...</td>', 'WHOA... Zeus at work :) Very cool...', '2006-06-22 00:46:23.000000', NULL, 1),
(2539388, 348969, 58785, '<td valign="top">I liked the way clouds came out :D</td>', 'I liked the way clouds came out :D', '2006-06-22 00:46:47.000000', NULL, 1),
(2539392, 348464, 58785, '<td valign="top">Cool... It looks like headband on earth :)</td>', 'Cool... It looks like headband on earth :)', '2006-06-22 00:47:20.000000', NULL, 1),
(2539395, 350990, 58785, '<td valign="top">Very nice softening affect :)</td>', 'Very nice softening affect :)', '2006-06-22 00:47:41.000000', NULL, 1),
