(2540355, 350982, 24073, '<td valign="top">Im cool with this photo, because the colors are absolutely magnificent.  The photo is strikingly cool, and fresh, as much so as relaxing and calm.  I think you have done a wonderful job, and I hope that this photo gets the credit it deserves.  GL 8+</td>', 'Im cool with this photo, because the colors are absolutely magnificent.  The photo is strikingly cool, and fresh, as much so as relaxing and calm.  I think you have done a wonderful job, and I hope that this photo gets the credit it deserves.  GL 8+', '2006-06-22 09:49:03.000000', NULL, 1),
(2540356, 350511, 23098, '<td valign="top">Like the colors here.</td>', 'Like the colors here.', '2006-06-22 09:49:03.000000', NULL, 1),
