(2540368, 349875, 23098, '<td valign="top">Good reflections.</td>', 'Good reflections.', '2006-06-22 09:53:47.000000', NULL, 1),
(2540369, 350206, 24073, '<td valign="top">Your photo is flat!  Not that it is a bad photo by any means, it is quite nice, but with the clouds and reflection of light being blown out, and the boats being a little fuzzy I think it would do much better with a crisper, darker mood.  Also something I notice is the water, it must have been a breezy evening or morning, because the water has distorted your reflections.  Still a nice photo, GL.</td>', 'Your photo is flat!  Not that it is a bad photo by any means, it is quite nice, but with the clouds and reflection of light being blown out, and the boats being a little fuzzy I think it would do much better with a crisper, darker mood.  Also something I notice is the water, it must have been a breezy evening or morning, because the water has distorted your reflections.  Still a nice photo, GL.', '2006-06-22 09:54:22.000000', NULL, 1),
(2540371, 350194, 23098, '<td valign="top">Well done, I tried to catch the second hand but with no success.</td>', 'Well done, I tried to catch the second hand but with no success.', '2006-06-22 09:54:39.000000', NULL, 1),
(2540374, 350023, 24073, '<td valign="top">Very well done, the composition along with the mood are stunning.</td>', 'Very well done, the composition along with the mood are stunning.', '2006-06-22 09:55:23.000000', NULL, 1),
(2540375, 349690, 23098, '<td valign="top">Great star trails.</td>', 'Great star trails.', '2006-06-22 09:55:34.000000', NULL, 1),
(2540377, 349943, 24073, '<td valign="top">Im getting hardly nothing here, I think my monitor might be a tad off, but the photo is very, very dark and quite blurry.</td>', 'Im getting hardly nothing here, I think my monitor might be a tad off, but the photo is very, very dark and quite blurry.', '2006-06-22 09:56:23.000000', NULL, 1),
(2540378, 348603, 24073, '<td valign="top">simple and beautiful, great job.</td>', 'simple and beautiful, great job.', '2006-06-22 09:56:46.000000', NULL, 1),
