INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2540551, 348886, 24073, '<td valign="top">Very good, one to treasure.  If this was my daughter I would frame and hang this one on the wall.  Very nice job, well executed.  GL.</td>', 'Very good, one to treasure.  If this was my daughter I would frame and hang this one on the wall.  Very nice job, well executed.  GL.', '2006-06-22 10:34:17.000000', NULL, 1),
(2540555, 350581, 24073, '<td valign="top">You got some lens fuzzies, Im sure you noticed that.  GL.</td>', 'You got some lens fuzzies, Im sure you noticed that.  GL.', '2006-06-22 10:35:01.000000', NULL, 1),
(2540567, 348705, 24073, '<td valign="top">Deeply gratifying to the eyes.  My eyes anyway, GL, if this doesn''t ribbon it wont be because of me.</td>', 'Deeply gratifying to the eyes.  My eyes anyway, GL, if this doesn''t ribbon it wont be because of me.', '2006-06-22 10:37:38.000000', NULL, 1),
(2540575, 350028, 24073, '<td valign="top">Good.  Love the composition here.  Executed to the tee.  Nice job, and GL.<br/>Still don''t get how ya''ll get these.</td>', 'Good.  Love the composition here.  Executed to the tee.  Nice job, and GL.Still don''t get how ya''ll get these.', '2006-06-22 10:39:47.000000', NULL, 1),
(2540580, 349888, 24073, '<td valign="top">A ribbon pick in my book, if not a serious contender.  Great Job, I''d hang it on my wall any day.</td>', 'A ribbon pick in my book, if not a serious contender.  Great Job, I''d hang it on my wall any day.', '2006-06-22 10:41:18.000000', NULL, 1),
(2540590, 348505, 24073, '<td valign="top">Not a IR fan, but I am also not a fantasy fan.  At any rate, I don''t vote on my personal likes or dislikes,  you captured a great image that is technically well done, and the composition is also fantastic.  GL.</td>', 'Not a IR fan, but I am also not a fantasy fan.  At any rate, I don''t vote on my personal likes or dislikes,  you captured a great image that is technically well done, and the composition is also fantastic.  GL.', '2006-06-22 10:45:55.000000', NULL, 1),
(2540596, 350466, 24073, '<td valign="top">This is fantastic.  Probably in my top 10, the problem for you and a possible ribbon pick, is you have very strong contenders in this challenge.  GL.</td>', 'This is fantastic.  Probably in my top 10, the problem for you and a possible ribbon pick, is you have very strong contenders in this challenge.  GL.', '2006-06-22 10:48:11.000000', NULL, 1),
(2540603, 348911, 24073, '<td valign="top">One night in my youth I took a spiritual journey, this is precisely what I remember. LOL.  Great Job, GL.</td>', 'One night in my youth I took a spiritual journey, this is precisely what I remember. LOL.  Great Job, GL.', '2006-06-22 10:51:48.000000', NULL, 1),
(2540610, 349399, 32754, '<td valign="top">this is good...the rocks in foreground are a wonderful touch of depth and texture; beautifully composed..</td>', 'this is good...the rocks in foreground are a wonderful touch of depth and texture; beautifully composed..', '2006-06-22 10:52:23.000000', NULL, 1),
(2540619, 350798, 32754, '<td valign="top">I like this image..it has a surreal unique feeling..the vortex effect makes this image fascinating.</td>', 'I like this image..it has a surreal unique feeling..the vortex effect makes this image fascinating.', '2006-06-22 10:54:43.000000', NULL, 1),
(2540620, 350529, 24073, '<td valign="top">The problem I see here, this is a photo thats not incredible, and not bad, but one that will probably be voted right in the middle, and probably voted on fast.  There is just nothing here that pops out, and makes you stop in passing.  I hope this isn''t to critical, because its not a bad photo, it just doesnt stand out from the crowd.  Hope this helps.  GL.</td>', 'The problem I see here, this is a photo thats not incredible, and not bad, but one that will probably be voted right in the middle, and probably voted on fast.  There is just nothing here that pops out, and makes you stop in passing.  I hope this isn''t to critical, because its not a bad photo, it just doesnt stand out from the crowd.  Hope this helps.  GL.', '2006-06-22 10:54:44.000000', NULL, 1),
(2540644, 348832, 32754, '<td valign="top">the tones of this image are wonderful, there is such a sense of serenity and yet movement..awesome picture..</td>', 'the tones of this image are wonderful, there is such a sense of serenity and yet movement..awesome picture..', '2006-06-22 11:02:17.000000', NULL, 1),
(2540656, 348705, 32754, '<td valign="top">lovely, serene image..I like it; the soft tones are beautiful..well done</td>', 'lovely, serene image..I like it; the soft tones are beautiful..well done', '2006-06-22 11:05:12.000000', NULL, 1),
(2540659, 349888, 32754, '<td valign="top">this image appeals to me; it''s a unique composition..the palms and the sky create an interesting visual effect.</td>', 'this image appeals to me; it''s a unique composition..the palms and the sky create an interesting visual effect.', '2006-06-22 11:06:26.000000', NULL, 1),
(2540661, 350510, 32754, '<td valign="top">I like this image..it has a neon look to it; simple and effective</td>', 'I like this image..it has a neon look to it; simple and effective', '2006-06-22 11:06:49.000000', NULL, 1),
(2540665, 347987, 32254, '<td valign="top">Hopefully it''s ''over'' 30 so it doesn''t get DQed, cool shot.</td>', 'Hopefully it''s ''over'' 30 so it doesn''t get DQed, cool shot.', '2006-06-22 11:08:23.000000', NULL, 1),
(2540667, 349106, 32754, '<td valign="top">wonderful image..soft tones, good composition.</td>', 'wonderful image..soft tones, good composition.', '2006-06-22 11:08:37.000000', NULL, 1),
(2540694, 349441, 50715, '<td valign="top">Entertaining idea, but the technicals are a real problem - horribly out of focus, tilt that looks like a mistake rather than deliberate, and mediocre central flaming. Fixing the focus and adjusting the framing to something a bit more interesting (e.g. move the toilet a bit to one side, and include the figure reaching for the toilet paper?) would not make it a ribbon winner, but would make a huge improvement.</td>', 'Entertaining idea, but the technicals are a real problem - horribly out of focus, tilt that looks like a mistake rather than deliberate, and mediocre central flaming. Fixing the focus and adjusting the framing to something a bit more interesting (e.g. move the toilet a bit to one side, and include the figure reaching for the toilet paper?) would not make it a ribbon winner, but would make a huge improvement.', '2006-06-22 11:27:15.000000', NULL, 1),
(2540699, 349038, 50715, '<td valign="top">Too dark, needs longer exposure or wider aperture or a slightly different angle to bring out some more detail in the fence.</td>', 'Too dark, needs longer exposure or wider aperture or a slightly different angle to bring out some more detail in the fence.', '2006-06-22 11:28:44.000000', NULL, 1),
(2540705, 350846, 50715, '<td valign="top">Interesting idea, but I think you''ve manipulated it too much. I can see banding in the sky colours, particularly toward the top left corner. The red in the centre of the frame is a bit too overpowering.</td>', 'Interesting idea, but I think you''ve manipulated it too much. I can see banding in the sky colours, particularly toward the top left corner. The red in the centre of the frame is a bit too overpowering.', '2006-06-22 11:30:37.000000', NULL, 1),
(2540713, 349084, 58873, '<td valign="top">hahahahahha run dude run!</td>', 'hahahahahha run dude run!', '2006-06-22 11:34:17.000000', NULL, 1),
(2540715, 348603, 58873, '<td valign="top">coooooooooooooooooooooool</td>', 'coooooooooooooooooooooool', '2006-06-22 11:35:35.000000', NULL, 1),
(2540720, 350511, 58873, '<td valign="top">yeeeeah</td>', 'yeeeeah', '2006-06-22 11:37:10.000000', NULL, 1),
