(2540964, 350155, 22748, '<td valign="top">Interesting shot, I have not seen one like this before. Pretty cool.</td>', 'Interesting shot, I have not seen one like this before. Pretty cool.', '2006-06-22 13:00:04.000000', NULL, 1),
