(2544860, 349007, 51793, '<td valign="top">How neat!!!!!!!!! I love it :-)</td>', 'How neat!!!!!!!!! I love it :-)', '2006-06-23 12:16:52.000000', NULL, 1),
(2544865, 350053, 60303, '<td valign="top">Oooooh...!!  Im not even sure what to say to be honest...I love this!</td>', 'Oooooh...!!  Im not even sure what to say to be honest...I love this!', '2006-06-23 12:19:54.000000', NULL, 1),
(2544881, 349873, 5792, '<td valign="top">Very, very nice astronomy shot. Good colors, good tracking. Might consider sharpening more to make the individual stars stand out more, especially the high density galactic plane ones on the left.</td>', 'Very, very nice astronomy shot. Good colors, good tracking. Might consider sharpening more to make the individual stars stand out more, especially the high density galactic plane ones on the left.', '2006-06-23 12:29:17.000000', NULL, 1),
(2544887, 350196, 60995, '<td valign="top">Love the head-on perspective, brown colors at night, texture of the dock.  One of the few I looked at for more than 5 seconds.</td>', 'Love the head-on perspective, brown colors at night, texture of the dock.  One of the few I looked at for more than 5 seconds.', '2006-06-23 12:32:35.000000', NULL, 1),
(2544888, 348910, 60303, '<td valign="top">A whole story in one pic....imaginative!</td>', 'A whole story in one pic....imaginative!', '2006-06-23 12:32:40.000000', NULL, 1),
(2544896, 350036, 60303, '<td valign="top">Oh my...this is an amazing shot.  One of my favorites even.</td>', 'Oh my...this is an amazing shot.  One of my favorites even.', '2006-06-23 12:34:44.000000', NULL, 1),
(2544898, 349689, 60995, '<td valign="top">Photo makes me want to know more about the place..and go there.  Great job.</td>', 'Photo makes me want to know more about the place..and go there.  Great job.', '2006-06-23 12:35:12.000000', NULL, 1),
(2544930, 348876, 60303, '<td valign="top">That *is* a beauty...!</td>', 'That *is* a beauty...!', '2006-06-23 12:42:47.000000', NULL, 1),
(2544938, 350884, 60995, '<td valign="top">Unique subject.  Photo calls attention to the beauty of an "everyday" object.</td>', 'Unique subject.  Photo calls attention to the beauty of an "everyday" object.', '2006-06-23 12:44:17.000000', NULL, 1),
(2544939, 348603, 60303, '<td valign="top">Hehehe...cute</td>', 'Hehehe...cute', '2006-06-23 12:44:31.000000', NULL, 1),
(2544948, 350044, 60303, '<td valign="top">What beautiful scenery!  Would have been perfect if the plants in the front were in focus, but I guess they were swaying in the wind...</td>', 'What beautiful scenery!  Would have been perfect if the plants in the front were in focus, but I guess they were swaying in the wind...', '2006-06-23 12:46:20.000000', NULL, 1),
