(2549337, 349758, 51802, '<td valign="top">I think this might do better if you could have shown the passage of time in this shot.  The minute hand is too crisp.</td>', 'I think this might do better if you could have shown the passage of time in this shot.  The minute hand is too crisp.', '2006-06-24 19:01:24.000000', NULL, 1),
(2549344, 349581, 51802, '<td valign="top">I think this is a great idea, but I believe it would have worked better if the candle was stationary.</td>', 'I think this is a great idea, but I believe it would have worked better if the candle was stationary.', '2006-06-24 19:05:28.000000', NULL, 1),
(2549356, 348886, 51802, '<td valign="top">Well done!  Only complaint is that the model''s arms overlap slightly.</td>', 'Well done!  Only complaint is that the model''s arms overlap slightly.', '2006-06-24 19:08:57.000000', NULL, 1),
(2549359, 350331, 51802, '<td valign="top">I really like how there is very little bluring, but there are still some well definied ghosts!</td>', 'I really like how there is very little bluring, but there are still some well definied ghosts!', '2006-06-24 19:10:12.000000', NULL, 1),
(2549378, 349978, 51802, '<td valign="top">Too blown out for my taste.</td>', 'Too blown out for my taste.', '2006-06-24 19:16:23.000000', NULL, 1),
(2549408, 350511, 6667, '<td valign="top">As many times as I have seen this it still leaves me in awe! You and your camera have done it justice!  Nicely done.  BOL 8</td>', 'As many times as I have seen this it still leaves me in awe! You and your camera have done it justice!  Nicely done.  BOL 8', '2006-06-24 19:30:52.000000', NULL, 1),
(2549413, 349930, 6667, '<td valign="top">Stunning.  BOL 9</td>', 'Stunning.  BOL 9', '2006-06-24 19:32:44.000000', NULL, 1),
