(2552156, 351035, 33392, '<td valign="top">Neat photo by all measures - color, focus, composition.</td>', 'Neat photo by all measures - color, focus, composition.', '2006-06-25 17:48:19.000000', NULL, 1),
(2552158, 349954, 33392, '<td valign="top">The subject itself could be more interesting, but well done.</td>', 'The subject itself could be more interesting, but well done.', '2006-06-25 17:48:49.000000', NULL, 1),
