(2552180, 349732, 33392, '<td valign="top">Not war.<br/> <br/>Technically well done, but not the most interesting subject in the challenge.</td>', 'Not war. Technically well done, but not the most interesting subject in the challenge.', '2006-06-25 17:53:26.000000', NULL, 1),
(2552181, 348808, 33392, '<td valign="top">I''m not sure that I get why it''s on water, but the clock itself is pretty cool.</td>', 'I''m not sure that I get why it''s on water, but the clock itself is pretty cool.', '2006-06-25 17:54:02.000000', NULL, 1),
(2552185, 350194, 33392, '<td valign="top">Neat enough, but there is some pretty stiff clock-competition in this challenge.</td>', 'Neat enough, but there is some pretty stiff clock-competition in this challenge.', '2006-06-25 17:54:30.000000', NULL, 1),
(2552203, 348832, 49326, '<td valign="top">Too blue</td>', 'Too blue', '2006-06-25 18:03:42.000000', NULL, 1),
(2552205, 349084, 49326, '<td valign="top">I''ve done that once. It''s is much fun. 8!</td>', 'I''ve done that once. It''s is much fun. 8!', '2006-06-25 18:05:24.000000', NULL, 1),
(2552383, 350187, 3032, '<td valign="top">There it is again. :)<br/>The balance of the exposure is a bit off, too dark foreground, to light sky. This could be better when shot when it is darker. A bit difficult in Scandinavia at this time of the year, you are celebrating the summer night this week right? :)<br/>Also the horizon is pretty centered, that makes it difficult for the eye and mind to determine what the most important aspect is here. The foreground rocks and reflections or the upper brighter part with the tower.</td>', 'There it is again. :)The balance of the exposure is a bit off, too dark foreground, to light sky. This could be better when shot when it is darker. A bit difficult in Scandinavia at this time of the year, you are celebrating the summer night this week right? :)Also the horizon is pretty centered, that makes it difficult for the eye and mind to determine what the most important aspect is here. The foreground rocks and reflections or the upper brighter part with the tower.', '2006-06-25 19:05:52.000000', NULL, 1),
(2552388, 349441, 54540, '<td valign="top">Brilliant!  You made me laugh!  (I wish the focus were better though)  Clever idea.</td>', 'Brilliant!  You made me laugh!  (I wish the focus were better though)  Clever idea.', '2006-06-25 19:07:35.000000', NULL, 1),
(2552392, 350041, 3032, '<td valign="top">Nice composition and clarity here. The reflection adds a lot.</td>', 'Nice composition and clarity here. The reflection adds a lot.', '2006-06-25 19:09:03.000000', NULL, 1),
(2552398, 349134, 3032, '<td valign="top">Nice colors, clarity and composition.</td>', 'Nice colors, clarity and composition.', '2006-06-25 19:10:04.000000', NULL, 1),
(2552403, 349690, 3032, '<td valign="top">Pretty cool, I''ve always wanted to do is but it hard to find a good dark place in our crowded little overexposed country. :(</td>', 'Pretty cool, I''ve always wanted to do is but it hard to find a good dark place in our crowded little overexposed country. :(', '2006-06-25 19:11:39.000000', NULL, 1),
(2552406, 350798, 3032, '<td valign="top">Wow, strange, but cool effect.</td>', 'Wow, strange, but cool effect.', '2006-06-25 19:13:22.000000', NULL, 1),
(2552407, 350053, 3032, '<td valign="top">Love the calm mood of this, probably because of the soft tints and how the reflections fades into blur.</td>', 'Love the calm mood of this, probably because of the soft tints and how the reflections fades into blur.', '2006-06-25 19:14:32.000000', NULL, 1),
(2552409, 350044, 3032, '<td valign="top">Looks a bit like Bear stuff.<br/>Nice flow in the composition and I like the colors.</td>', 'Looks a bit like Bear stuff.Nice flow in the composition and I like the colors.', '2006-06-25 19:15:57.000000', NULL, 1),
(2552411, 350982, 54540, '<td valign="top">The abstract qualities of this image are FANTASTIC!  Well done.  I can''t keep my eyes off it.</td>', 'The abstract qualities of this image are FANTASTIC!  Well done.  I can''t keep my eyes off it.', '2006-06-25 19:17:26.000000', NULL, 1),
