(2552567, 349419, 13084, '<td valign="top">WWWOOOOWWW, this is a ribbon for sure.  Love the color, the smooth water, the yoga people, the position of everything. A 10. Good luck!</td>', 'WWWOOOOWWW, this is a ribbon for sure.  Love the color, the smooth water, the yoga people, the position of everything. A 10. Good luck!', '2006-06-25 20:41:35.000000', NULL, 1),
