(2554039, 350196, 60036, '<td valign="top">The out of focus background keeps drawing my eye. The texture of the pier would have been really brought out with a crop removing the bright lights in the sky.</td>', 'The out of focus background keeps drawing my eye. The texture of the pier would have been really brought out with a crop removing the bright lights in the sky.', '2006-06-26 06:20:44.000000', NULL, 1),
(2554045, 349232, 60036, '<td valign="top">To me the person detracts from the image, adding a blur where the land shows great detail and the water adds a mistiness. A little colour adjustment to bring out the grass and lichen and this would be excellent.</td>', 'To me the person detracts from the image, adding a blur where the land shows great detail and the water adds a mistiness. A little colour adjustment to bring out the grass and lichen and this would be excellent.', '2006-06-26 06:25:25.000000', NULL, 1),
